using System;
using System.Data;
using System.Web.UI;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Controls.Report
{
    public partial class StudentSearchInfo : ControlBase
    {
        #region Const

        private const string PERMISSION_VIEW = "frmStudentSearchInfo_View";
        private const string STORE_NAME = "Sim_student_searchinfo_print";

        #endregion

        #region Private Methods

        private void ClearCard()
        {
            pnlCard.Visible = false;
            pnlPrintActions.Visible = false;
            pnlEmpty.Visible = false;

            litFullName.Text = "";
            litStudentCode.Text = "";
            litPersonId.Text = "";
            litPersonIdDate.Text = "";
            litPersonIdPlace.Text = "";
            litIsDriverCer.Text = "";
            litDriverCerNo.Text = "";
            litDriverCerDate.Text = "";
            litDriverCerPlace.Text = "";
        }

        private string GetText(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";
            return value.ToString().Trim();
        }

        private string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value || value.ToString() == "")
                return "";

            DateTime dtmValue;
            if (DateTime.TryParse(value.ToString(), out dtmValue))
                return dtmValue.ToString("dd/MM/yyyy");

            return value.ToString();
        }

        private string FormatBool(object value)
        {
            if (value == null || value == DBNull.Value || value.ToString() == "")
                return "";

            bool bolValue;
            if (bool.TryParse(value.ToString(), out bolValue))
                return bolValue ? "Có" : "Không";

            if (value.ToString() == "1")
                return "Có";
            if (value.ToString() == "0")
                return "Không";

            return value.ToString();
        }

        private void BindCard(DataRow drw)
        {
            litFullName.Text = GetText(drw["FullName"]);
            litStudentCode.Text = GetText(drw["Studentcode"]);
            litPersonId.Text = GetText(drw["Personid"]);
            litPersonIdDate.Text = FormatDate(drw["Persioniddate"]);
            litPersonIdPlace.Text = GetText(drw["Persionidplace"]);
            litIsDriverCer.Text = FormatBool(drw["IsDriverCer"]);
            litDriverCerNo.Text = GetText(drw["DriverCerNo"]);
            litDriverCerDate.Text = FormatDate(drw["DriverCerDate"]);
            litDriverCerPlace.Text = GetText(drw["DriverCerPlace"]);

            pnlCard.Visible = true;
            pnlPrintActions.Visible = true;
            pnlEmpty.Visible = false;
        }

        private void LoadData()
        {
            ClearCard();

            if (User == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            string strStudentCode = txtStudentCode.Text.Trim();
            if (strStudentCode == "")
            {
                MsgBox.ShowWarning("Vui lòng nhập mã học viên!");
                txtStudentCode.Focus();
                return;
            }

            SIM_Branch obj = new SIM_Branch();
            DataTable dtbData = obj.GetDataTable(STORE_NAME, "@StudentCode", strStudentCode);

            if (dtbData == null)
            {
                MsgBox.ShowError("Việc tải thông tin bị lỗi!");
                return;
            }

            if (dtbData.Rows.Count == 0)
            {
                pnlEmpty.Visible = true;
                litEmptyMessage.Text = String.Format("Không tìm thấy học viên với mã \"{0}\".", strStudentCode);
                return;
            }

            BindCard(dtbData.Rows[0]);
        }

        #endregion

        #region Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (User == null || !WebGlobal.HasPermission(PERMISSION_VIEW))
                {
                    MsgBox.ShowWarning("Bạn không có quyền truy cập chức năng này!");
                    this.Visible = false;
                    return;
                }
            }
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            LoadData();
        }

        protected void btnPrint1_Click(object sender, EventArgs e)
        {
            // Chờ cơ chế in
        }

        protected void btnPrint2_Click(object sender, EventArgs e)
        {
            // Chờ cơ chế in
        }

        #endregion
    }
}

